// Zweck: Hinweis auf die KI in der ersten Antwort einer Sitzung (Art. 50 Abs. 1 und 5 der KI-Verordnung). Der Hinweis kommt aus dem Workflow, nicht aus dem Modell.
// Der Chat zeigt wegen responseMode lastNode die Antwort des letzten Knotens, deshalb laufen alle Endknoten hier zusammen.
const KI_HINWEIS = 'Hinweis: Du schreibst mit einer KI, nicht mit einem Menschen.';
const ENDEN = ['Antwort setzen [Edit Fields]', 'Eingang abgelehnt [Edit Fields]', 'Antwort ohne Freigabe [Edit Fields]', 'Freigabe-Fehler [Edit Fields]', 'Ergebnis Sperre [Edit Fields]', 'Meldung fehlgeschlagen [Edit Fields]', 'Verwerfen gemeldet [Edit Fields]', 'Ergebnis Entscheidung [Edit Fields]', 'Ergebnis Ablage [Edit Fields]'];
const hinweise = [];
let ende = '', antwort = '', felder = {};
for (const name of ENDEN) {
  try {
    const k = $(name); // wirft, wenn der Knoten (noch) nicht existiert, zum Beispiel der frühere Endknoten Antwort setzen
    if (k.isExecuted) { felder = k.first().json || {}; ende = name; antwort = String(felder.output ?? ''); break; }
  } catch (e) { hinweise.push(name + ': ' + String(e.message).slice(0, 80)); }
}
if (!ende || !antwort) throw new Error('KI-Hinweis: kein Endknoten mit Antwort gefunden (' + hinweise.length + ' nicht lesbar).');
// Alle Läufe von Sitzung prüfen in dieser Ausführung ansehen, Erfolgs- und Fehlerausgang: war einer "neu", ist das die erste Antwort der Sitzung.
const laeufe = [];
for (let i = 0; i <= $runIndex; i++) {
  for (const zweig of [0, 1]) {
    try { laeufe.push(...$('Sitzung prüfen [HTTP Request]').all(zweig, i).map(x => x.json || {})); }
